import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { describe, expect, it, vi } from 'vitest'
import { IssueCard } from '../components/IssueCard'
import { makeIssue } from './fakeApi'

const issue = makeIssue(5, { _id: 'abc', title: 'Footer links are broken', status: 'open' })

describe('IssueCard actions', () => {
  it('shows no Status dropdown and no Delete button when no callbacks are given', () => {
    render(<IssueCard issue={issue} />)
    expect(screen.queryByLabelText('Status')).not.toBeInTheDocument()
    expect(screen.queryByRole('button', { name: 'Delete' })).not.toBeInTheDocument()
  })

  it('shows a Status dropdown set to the issue status', () => {
    render(<IssueCard issue={issue} onStatusChange={vi.fn()} />)
    expect(screen.getByLabelText('Status')).toHaveValue('open')
  })

  it('calls onStatusChange with the _id and the new status', async () => {
    const onStatusChange = vi.fn()
    render(<IssueCard issue={issue} onStatusChange={onStatusChange} />)
    await userEvent.selectOptions(screen.getByLabelText('Status'), 'closed')
    expect(onStatusChange).toHaveBeenCalledTimes(1)
    expect(onStatusChange).toHaveBeenCalledWith('abc', 'closed')
  })

  it('asks "Delete this issue?" first and does not delete yet', async () => {
    const onDelete = vi.fn()
    render(<IssueCard issue={issue} onDelete={onDelete} />)
    await userEvent.click(screen.getByRole('button', { name: 'Delete' }))
    expect(screen.getByText('Delete this issue?')).toBeInTheDocument()
    expect(onDelete).not.toHaveBeenCalled()
  })

  it('goes back to normal when Cancel is clicked', async () => {
    const onDelete = vi.fn()
    render(<IssueCard issue={issue} onDelete={onDelete} />)
    await userEvent.click(screen.getByRole('button', { name: 'Delete' }))
    await userEvent.click(screen.getByRole('button', { name: 'Cancel' }))
    expect(screen.queryByText('Delete this issue?')).not.toBeInTheDocument()
    expect(screen.getByRole('button', { name: 'Delete' })).toBeInTheDocument()
    expect(onDelete).not.toHaveBeenCalled()
  })

  it('calls onDelete with the _id only after "Yes, delete"', async () => {
    const onDelete = vi.fn()
    render(<IssueCard issue={issue} onDelete={onDelete} />)
    await userEvent.click(screen.getByRole('button', { name: 'Delete' }))
    await userEvent.click(screen.getByRole('button', { name: 'Yes, delete' }))
    expect(onDelete).toHaveBeenCalledTimes(1)
    expect(onDelete).toHaveBeenCalledWith('abc')
  })
})
